const audio={ctx:null,musicTimer:null,musicNote:0,active:[],duck:false,voiceWarned:new Set(),
 init(){try{this.ctx ||= new (window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch{}},
 tone(freq,dur,vol,type='sine',delay=0){if(!this.ctx||state.settings.mute)return;try{const o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=this.ctx.currentTime+delay;o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+dur+.02);this.active.push(g);o.onended=()=>{this.active=this.active.filter(x=>x!==g);o.disconnect();g.disconnect();};}catch{}},
 fx(kind){if(!state.settings.fx||state.settings.mute)return;this.init();const v=state.settings.fxVolume*.15;if(kind==='correct'){[523.25,659.25,783.99].forEach((n,i)=>this.tone(n,.4,v,'sine',i*.09));}else if(kind==='wrong')this.tone(261.63,.25,v*.5);else this.tone(440,.09,v*.3);},
 update(){if(!state.settings.music||state.settings.mute||view==='garden'||document.hidden){clearInterval(this.musicTimer);this.musicTimer=null;}else if(this.ctx&&!this.musicTimer){this.musicTimer=setInterval(()=>{const notes=[261.63,329.63,392,493.88,392,329.63,293.66,392];this.tone(notes[this.musicNote++%notes.length],1.6,state.settings.musicVolume*(this.duck?.012:.055));},1500);}
 if(state.settings.mute||document.hidden||view==='garden')this.active.forEach(g=>{try{g.gain.cancelScheduledValues(this.ctx.currentTime);g.gain.setTargetAtTime(.0001,this.ctx.currentTime,.03);}catch{}});},
 stopSpeech(){voiceTurn++;narrator?.stop();this.duck=false;},
 speak(text,lang='en',options={}){return narrator?.speak(text,lang,options);}
};
narrator=window.GalaxyNarrator.create({settings:()=>state.settings,onStatus:toast,onSpeaking:active=>{audio.duck=active;const status=$('#narration-status');if(status)status.textContent=active?'Nova is speaking…':'Ready when you are.';}});
if(window.GALAXY_VOICE_PACK){const result=narrator.setPack(window.GALAXY_VOICE_PACK);if(!result.ok)toast('The included voice pack could not load. Please open the complete Adventure Edition download.');}
function speech(text,lang='en',options={}){return audio.speak(text,lang,options);}
function manualSpeech(text,lang='en'){voiceTurn++;quranPlayer?.stop?.();if(state.settings.mute||!state.settings.voice||state.settings.voiceVolume===0){toast('Narration is off or muted. Use Enable & test Arabic in Settings to restore it.');return Promise.resolve(false);}return speech(text,lang,{interrupt:true});}
async function speechSequence(parts,lang='en'){const turn=++voiceTurn;for(const part of parts.filter(Boolean)){if(turn!==voiceTurn)return false;const played=await speech(part,lang);if(!played||turn!==voiceTurn)return false;}return true;}
const lastCheer={};
function cheer(kind,lang='en'){if(!state.settings.encouragement)return '';const pool=window.GALAXY_CHEERS[lang]?.[kind]||window.GALAXY_CHEERS.en[kind];const choices=pool.filter(x=>x!==lastCheer[lang+kind]);const text=choices[Math.floor(Math.random()*choices.length)]||pool[0];lastCheer[lang+kind]=text;return text;}
function encourage(kind,detail,lang='en'){const praise=cheer(kind,lang);speechSequence([praise,detail],lang);return [praise,detail].filter(Boolean).join(' ');}
function restoreVoices(){audio.stopSpeech();Object.assign(state.settings,{voiceSource:'pack',voice:true,mute:false,voiceVolume:.8,rate:1,voiceRevision:3});save();applySettings();}
async function arabicCheck(){restoreVoices();if(view!=='settings')navigate('settings');else renderSettings();const status=$('#narration-status');if(status)status.textContent='Playing the included Arabic sample…';const played=await manualSpeech('مرحبًا يا صديقي. هيا نتعلم معًا.','ar');if(view==='settings'&&$('#narration-status'))$('#narration-status').textContent=played?'Arabic sample finished. If it was silent, check your browser tab and computer audio output.':'The Arabic sample could not play. Check the message above and press Enable & test Arabic again.';}


function renderIcons(r=document){$$('[data-icon]',r).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const navs=[['home','home','Mission control'],['journey','map','My adventures'],['worlds','planet','Learning worlds'],['studio','pencil','Creative studio'],['garden','moon','Qur’an garden'],['collection','award','My collection']];
